class Solution {
public:
    int minimumCost(string target, vector<string>& words, vector<int>& costs) {
        int n = target.size();
        vector<long long> dp(n + 1, 1e18);
        dp[0] = 0;
        unordered_map<string, int> word_cost;
        for (int i = 0; i < words.size(); ++i) {
            if (!word_cost.count(words[i]) || costs[i] < word_cost[words[i]]) {
                word_cost[words[i]] = costs[i];
            }
        }
        for (int i = 0; i < n; ++i) {
            if (dp[i] == 1e18) continue;
            for (const auto& [w, c] : word_cost) {
                if (i + w.size() <= n && target.compare(i, w.size(), w) == 0) {
                    dp[i + w.size()] = min(dp[i + w.size()], dp[i] + c);
                }
            }
        }
        return (dp[n] >= 1e18) ? -1 : dp[n];
    }
};

class Solution {
    public int minimumCost(String target, String[] words, int[] costs) {
        int n = target.length();
        long[] dp = new long[n + 1];
        Arrays.fill(dp, Long.MAX_VALUE / 2);
        dp[0] = 0;
        Map<String, Integer> wordCost = new HashMap<>();
        for (int i = 0; i < words.length; ++i) {
            if (!wordCost.containsKey(words[i]) || costs[i] < wordCost.get(words[i])) {
                wordCost.put(words[i], costs[i]);
            }
        }
        for (int i = 0; i < n; ++i) {
            if (dp[i] >= Long.MAX_VALUE / 4) continue;
            for (Map.Entry<String, Integer> entry : wordCost.entrySet()) {
                String w = entry.getKey();
                int c = entry.getValue();
                if (target.startsWith(w, i)) {
                    dp[i + w.length()] = Math.min(dp[i + w.length()], dp[i] + c);
                }
            }
        }
        return dp[n] >= Long.MAX_VALUE / 4 ? -1 : (int) dp[n];
    }
}

var minimumCost = function(target, words, costs) {
    const n = target.length;
    const dp = new Array(n + 1).fill(Infinity);
    dp[0] = 0;
    const wordCost = new Map();
    for (let i = 0; i < words.length; i++) {
        if (!wordCost.has(words[i]) || costs[i] < wordCost.get(words[i])) {
            wordCost.set(words[i], costs[i]);
        }
    }
    for (let i = 0; i < n; i++) {
        if (dp[i] === Infinity) continue;
        for (const [w, c] of wordCost.entries()) {
            if (target.startsWith(w, i)) {
                if (dp[i] + c < dp[i + w.length]) {
                    dp[i + w.length] = dp[i] + c;
                }
            }
        }
    }
    return dp[n] === Infinity ? -1 : dp[n];
};
